import type { NoteStore } from './note-store.ts';
import { type Result, ok, err } from './result.ts';
import { searchNotes } from './search.ts';

export interface RouteRequest {
  params: string[];
  query: URLSearchParams;
  body: unknown;
}

export type Handler = (store: NoteStore, req: RouteRequest) => Result<unknown>;

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

export const createNote: Handler = (store, req) => {
  const b = req.body;
  if (!isRecord(b) || typeof b.title !== 'string' || typeof b.body !== 'string') {
    return err('title and body must be strings');
  }
  return store.add(b.title, b.body);
};

export const listNotes: Handler = (store) => ok(store.list());

export const getNote: Handler = (store, req) => {
  const raw = req.params[0] ?? '';
  return /^\d+$/.test(raw) ? store.get(Number(raw)) : err('not found');
};

export const search: Handler = (store, req) => searchNotes(store.list(), req.query.get('q') ?? '');

export const health: Handler = () => ok({ status: 'ok' });
