const errorStatus: Record<string, number> = { 'not found': 404, 'payload too large': 413 };
const statusFor = (error: string): number => errorStatus[error] ?? 400;

function parseJson(text: string): Result<unknown> {
  try {
    return ok(JSON.parse(text));
  } catch {
    return err('invalid json');
  }
}

function readBody(req: IncomingMessage): Promise<Result<unknown>> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size <= MAX_BODY) chunks.push(c);
    });
    req.on('error', () => resolve(err('invalid json')));
    req.on('end', () => {
      resolve(size > MAX_BODY ? err('payload too large') : parseJson(Buffer.concat(chunks).toString('utf8')));
    });
  });
}

function findRoute(method: string, path: string): { route: Route; params: string[] } | undefined {
  for (const route of routes) {
    const m = route.method === method ? route.pattern.exec(path) : null;
    if (m) return { route, params: m.slice(1) };
  }
  return undefined;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) });
  res.end(payload);
}

function respond(res: ServerResponse, result: Result<unknown>, okStatus: number): void {
  if (result.ok) send(res, okStatus, result.value);
  else send(res, statusFor(result.error), { error: result.error });
}

async function dispatch(store: NoteStore, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const found = findRoute(req.method ?? '', url.pathname);
  if (!found) {
    req.resume();
    return respond(res, err('not found'), 200);
  }
  const { route, params } = found;
  const body = route.hasBody ? await readBody(req) : ok(undefined);
  if (!body.ok) return respond(res, body, route.status);
  respond(res, route.handler(store, { params, query: url.searchParams, body: body.value }), route.status);
}

function logOnFinish(req: IncomingMessage, res: ServerResponse, log: Logger): void {
  const start = performance.now();
  const path = (req.url ?? '/').split('?')[0];
  res.on('finish', () => {
    log(JSON.stringify({ method: req.method, path, status: res.statusCode, ms: Math.round((performance.now() - start) * 100) / 100 }));
  });
}

export function createServer(store: NoteStore, log: Logger = (l) => console.log(l)): http.Server {
  return http.createServer((req, res) => {
    logOnFinish(req, res, log);
    dispatch(store, req, res).catch(() => {
      if (!res.headersSent) send(res, 500, { error: 'internal error' });
    });
  });
}
