import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import type { AddressInfo } from 'node:net';
import { NoteStore } from '../src/note-store.ts';
import { createServer } from '../src/http-edge.ts';

function runSmoke(url: string): Promise<{ code: number | null; out: string }> {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, ['scripts/smoke.ts'], { env: { ...process.env, SMOKE_URL: url } });
    let out = '';
    p.stdout.on('data', (d) => (out += d));
    p.stderr.on('data', (d) => (out += d));
    p.on('close', (code) => resolve({ code, out }));
  });
}

async function listen(server: ReturnType<typeof createServer>): Promise<string> {
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
  return `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
}

test('AC-14 smoke exits 0 when every check passes', async () => {
  const server = createServer(new NoteStore(), () => {});
  const url = await listen(server);
  try {
    const { code, out } = await runSmoke(url);
    assert.equal(code, 0, out);
  } finally { server.close(); server.closeAllConnections(); }
});

test('AC-14 package.json defines npm run smoke', async () => {
  const pkg = (await import('../package.json', { with: { type: 'json' } })).default;
  assert.match(pkg.scripts.smoke, /scripts\/smoke\.ts/);
});

test('AC-15 smoke exits non-zero and names the failing step when unreachable', async () => {
  const server = createServer(new NoteStore(), () => {});
  const url = await listen(server);
  server.close(); server.closeAllConnections();
  const { code, out } = await runSmoke(url);
  assert.notEqual(code, 0);
  assert.match(out, /health/i);
});

test('AC-15 smoke exits non-zero and names the failing step when a check fails', async () => {
  const server = createServer(new NoteStore(), () => {});
  server.removeAllListeners('request');
  server.on('request', (req, res) => {
    res.setHeader('content-type', 'application/json');
    if (req.url === '/health') return void res.end('{"status":"ok"}');
    res.statusCode = 500; res.end('{"error":"boom"}');
  });
  const url = await listen(server);
  try {
    const { code, out } = await runSmoke(url);
